//! Makes a folder of random maps out of one map's symbol set.
//!
//! What a renderer is measured against is maps, and there are never enough of
//! them: the ones which exist are somebody's copyright, cover the terrain
//! somebody happened to survey, and between them use a fraction of the
//! symbols a symbol set holds. A random map has none of those problems. It
//! can be generated by the hundred, in any symbol set, and it can be made to
//! put a symbol next to a symbol no surveyor ever would — which is exactly
//! where a renderer goes wrong.
//!
//! A map is built in three steps, and this module is what runs them:
//!
//! 1. the symbol set is sorted into the kinds a generator draws with — see
//!    [`crate::symbol_kinds`];
//! 2. the ground is divided into cells with wandering sides — see
//!    [`crate::layout`];
//! 3. the cells are filled in and drawn over. *Not written yet*: for now a
//!    generated map is its layout, drawn with a single line symbol, which is
//!    what makes a layout something that can be looked at.
//!
//! Everything random comes from [`crate::random`] and from the seed in
//! [`Settings`], so the same settings give the same folder of maps, map for
//! map and coordinate for coordinate.
//!
//! The maps carry the source's whole symbol set and colour table, as the
//! source file spells them — not just the symbols they happen to use. The
//! colour table is the drawing order of a map and a symbol names a colour by
//! its place in it, so it goes out whole in any case; and a generated map is
//! meant to be opened, edited and drawn on with the rest of the set.

use std::path::{Path, PathBuf};

use crate::layout::Layout;
use crate::map::{Object, ObjectKind, PathObject};
use crate::random::Random;
use crate::symbol_kinds::{Catalogue, Entry};
use crate::xml_reader;
use crate::xml_writer::MapFile;

/// The default number of cells a generated map is across.
pub const DEFAULT_LAYOUT_SIZE: usize = 3;

/// The default width of one cell, in meters on the ground.
pub const DEFAULT_CELL_SIZE: u32 = 30;

/// The default number of maps in a dataset.
pub const DEFAULT_MAPS: usize = 10;

/// The line symbol the cell outlines are drawn with while there is nothing in
/// them yet.
pub const DEFAULT_BORDER_SYMBOL: &str = "Paved area, bounding line";

/// What a dataset is to be made of.
pub struct Settings {
    /// How many cells a map is across: a map is `layout_size` by
    /// `layout_size` cells.
    pub layout_size: usize,
    /// How wide one cell is, in meters on the ground.
    pub cell_size: u32,
    /// How many maps the folder is to hold.
    pub maps: usize,
    /// Whether the maps must keep to the IOF rules for what may be drawn
    /// where.
    ///
    /// Nothing reads it yet: it is step three's, which picks the symbols the
    /// cells are filled with, and a layout is the same layout either way. It
    /// is carried here so that a dataset generated now records the setting it
    /// was asked for.
    pub iof_rules: bool,
    /// What the randomness is seeded with. The same seed gives the same
    /// dataset; the n-th map of a dataset is seeded with `seed + n`, so a map
    /// keeps its shape however many maps are asked for.
    pub seed: u64,
    /// The name of the symbol the cell outlines are drawn with, see
    /// [`DEFAULT_BORDER_SYMBOL`].
    pub border_symbol: String,
}

impl Default for Settings {
    fn default() -> Settings {
        Settings {
            layout_size: DEFAULT_LAYOUT_SIZE,
            cell_size: DEFAULT_CELL_SIZE,
            maps: DEFAULT_MAPS,
            iof_rules: false,
            seed: 0,
            border_symbol: DEFAULT_BORDER_SYMBOL.to_string(),
        }
    }
}

/// What a run came to.
pub struct Summary {
    /// The maps written, in the order they were generated.
    pub written: Vec<PathBuf>,
    /// The symbol set the maps were built from, sorted into kinds.
    pub catalogue: Catalogue,
    /// The symbol the cell outlines were drawn with.
    pub border: Entry,
    /// The scale of the source map, which every generated map inherits.
    pub scale_denominator: i32,
    /// Complaints from reading the source map.
    pub warnings: Vec<String>,
}

/// A folder of random maps built on the symbol set of `source`, written into
/// `into`.
///
/// `into` is created if it is not there, and a map of a previous run under
/// the same name is overwritten.
pub fn create_dataset(
    source: &Path,
    into: &Path,
    settings: &Settings,
    mut progress: impl FnMut(usize, usize),
) -> Result<Summary, String> {
    if settings.layout_size == 0 {
        return Err("the layout size must be at least one cell".to_string());
    }
    if settings.cell_size == 0 {
        return Err("the cell size must be at least one meter".to_string());
    }

    let (mut map, warnings) = xml_reader::read_xml_map(source)?;
    map.resolve_references();
    let fragments = xml_reader::read_fragments(source)?;

    let catalogue = Catalogue::of(&map);
    if catalogue.is_empty() {
        return Err(format!(
            "{} does not hold a single symbol which draws anything",
            source.display()
        ));
    }
    let border = catalogue
        .named(&settings.border_symbol)
        .ok_or_else(|| {
            format!(
                "{} has no symbol named \"{}\"",
                source.display(),
                settings.border_symbol
            )
        })?
        .clone();

    std::fs::create_dir_all(into).map_err(|e| format!("cannot make {}: {e}", into.display()))?;

    // Map coordinates are in mm on the paper; a layout is in meters on the
    // ground.
    let mm_per_meter = 1000.0 / map.scale_denominator as f64;

    let mut written = Vec::with_capacity(settings.maps);
    for index in 0..settings.maps {
        // A seed of its own per map, so that the third map of a dataset is
        // the same map whether ten or a thousand were asked for.
        let mut random = Random::from_seed(settings.seed.wrapping_add(index as u64));
        let layout = Layout::random(settings.layout_size, settings.cell_size as f64, &mut random);

        let objects: Vec<Object> = layout
            .cell_outlines(mm_per_meter)
            .into_iter()
            .map(|coords| {
                let mut object = Object::new(ObjectKind::Path(PathObject::default()));
                object.coords = coords;
                object.symbol_index = Some(border.index);
                object.symbol_id = border.id;
                object
            })
            .collect();

        let path = into.join(map_name(index, settings.maps));
        MapFile {
            scale_denominator: map.scale_denominator,
            colors: &fragments.colors,
            symbols: &fragments.symbols,
            objects: &objects,
            rotatable: false,
        }
        .write(&path)?;
        written.push(path);
        progress(index + 1, settings.maps);
    }

    Ok(Summary {
        written,
        catalogue,
        border,
        scale_denominator: map.scale_denominator,
        warnings,
    })
}

/// The name of the n-th map of a dataset of `total`, zero padded far enough
/// that the folder sorts the way it was generated.
pub fn map_name(index: usize, total: usize) -> String {
    let width = total.max(1).to_string().len().max(3);
    format!("map_{:0width$}.omap", index + 1, width = width)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_map_name_is_padded_to_the_size_of_the_dataset() {
        assert_eq!(map_name(0, 10), "map_001.omap");
        assert_eq!(map_name(9, 10), "map_010.omap");
        // Never narrower than three digits, and wider where it must be.
        assert_eq!(map_name(0, 2), "map_001.omap");
        assert_eq!(map_name(999, 1000), "map_1000.omap");
    }
}
